from more_itertools import interleave_evenly, sliced, numeric_range
from itertools import product
from decimal import Decimal
from fractions import Fraction
from datetime import datetime, timedelta

for lengths in ([], [0], [0, 0], [0, 3], [3, 0], [0, 2, 0, 5]):
    inputs = [[(i, j) for j in range(n)] for i, n in enumerate(lengths)]
    for explicit in (False, True):
        actual = list(interleave_evenly(inputs, lengths=lengths if explicit else None))
        assert sorted(actual) == sorted(x for seq in inputs for x in seq)
        for i, seq in enumerate(inputs):
            assert [x for x in actual if x[0] == i] == seq
for strict in (False, True):
    for seq in ([], [1, 2, 3], 'abc'):
        try:
            sliced(seq, -1, strict=strict)
        except ValueError:
            pass
        else:
            raise AssertionError('negative size accepted')
    assert list(sliced([1, 2], 0, strict=strict)) == []

for start, stop, step in product(range(-5, 6), range(-5, 6), range(-4, 5)):
    if step:
        r = numeric_range(start, stop, step)
        assert list(reversed(r)) == list(range(start, stop, step))[::-1]
for typ in (float, Decimal, Fraction):
    for start, stop, step in product(('-1.2', '0', '0.1', '1.3'), ('-1.2', '0', '0.3', '1.3'), ('-0.3', '-0.1', '0.1', '0.3')):
        r = numeric_range(typ(start), typ(stop), typ(step))
        assert list(reversed(r)) == list(r)[::-1], (r, list(r), list(reversed(r)))
for step in (timedelta(hours=7), timedelta(hours=-7)):
    for start, stop in product((datetime(2024, 1, 1), datetime(2024, 1, 3)), repeat=2):
        r = numeric_range(start, stop, step)
        assert list(reversed(r)) == list(r)[::-1]
print('Targeted regression checks passed')
